def minNumberOfFrogs(croak):
    cnt = [0, 0, 0, 0]
    idx = {"r": 1, "o": 2, "a": 3, "k": 4}
    busy = 0
    best = 0
    for ch in croak:
        if ch == "c":
            cnt[0] += 1
            busy += 1
            if busy > best:
                best = busy
        else:
            k = idx[ch]
            if cnt[k - 1] == 0:
                return -1
            cnt[k - 1] -= 1
            if k < 4:
                cnt[k] += 1
            else:
                busy -= 1
    return best if busy == 0 else -1
